    // In-memory spill sink for testing the spill mechanism without LMDB.
    struct MemSpill { map: HashMap<u32, Vec<u64>>, puts: usize, gets: usize }
    impl SpillSink for MemSpill {
        fn spill_put(&mut self, node: u32, hist: &[u64]) { self.map.insert(node, hist.to_vec()); self.puts += 1; }
        fn spill_get(&mut self, node: u32) -> Option<Vec<u64>> { self.gets += 1; self.map.get(&node).cloned() }
    }

    // Spill fallback: a tiny live budget WITHOUT a sink stops early; WITH a sink the
    // sweep spills live entries and COMPLETES with identical band results.
    #[test]
    fn sweep_spill_completes_and_matches() {
        let mut vm = dag();
        let root = vm.intern_atom("0");
        let budget = 8usize;
        let bnodes: Vec<u32> = ["1", "2", "3", "4"].iter().map(|s| vm.intern_atom(s)).collect();
        // reference: unbudgeted sweep
        vm.build_boundary_suffix_sweep(&bnodes, root, budget, "category_parent", 0, 0).unwrap();
        let ref_tbl = snapshot_table(&vm);
        // tiny live budget, NO spill -> stop-at-depth (frontier can't fit)
        let no_spill = vm.build_boundary_suffix_sweep(&bnodes, root, budget, "category_parent", 0, 1).unwrap();
        assert!(no_spill.stopped_early, "live_budget=1 without spill should stop early");
        // tiny live budget, WITH spill -> completes, spills, identical results
        let mut spill = MemSpill { map: HashMap::new(), puts: 0, gets: 0 };
        let s = vm.build_boundary_suffix_sweep_with_spill(&bnodes, root, budget, "category_parent", 0, 1, &mut spill).unwrap();
        assert!(!s.stopped_early, "spill must not stop early");
        assert!(s.spilled > 0, "spill should have written live entries");
        assert!(spill.puts > 0 && spill.gets > 0, "sink should see puts and reload gets");
        assert_eq!(snapshot_table(&vm), ref_tbl, "spill must produce identical band results");
    }

    // The entry-frontier band is a thin cut (region surface, not volume) yet the
    // splice through it still matches full enumeration for periphery seeds. Graph
    // has a genuine periphery (nodes outside the root-near region).
    #[test]
    fn entry_frontier_band_is_thin_and_exact() {
        let mut vm = WamState::new(vec![], HashMap::new());
        // core near root 0, plus a periphery (10,11,12) hanging off the core.
        vm.register_ffi_fact_pairs("category_parent", &[
            ("1", "0"), ("2", "0"), ("3", "1"), ("4", "2"),
            ("10", "3"), ("10", "4"), ("11", "3"), ("12", "10"),
        ]);
        let root = vm.intern_atom("0");
        let budget = 8usize;
        let n = 2.0f64;
        let mut md: HashMap<i32, i32> = HashMap::new();
        for (name, d) in [("0",0),("1",1),("2",1),("3",2),("4",2),("10",3),("11",3),("12",4)] {
            md.insert(vm.intern_atom(name) as i32, d);
        }
        vm.set_min_dist(&md);
        // d_pre=2: whole region is {1,2,3,4}; entry frontier is just {3,4}
        // (the region nodes the periphery attaches to).
        let region = vm.boundary_band_root_near(2);
        let frontier = vm.boundary_band_entry_frontier(2, "category_parent");
        assert!(frontier.len() < region.len(),
            "entry frontier {} should be thinner than region {}", frontier.len(), region.len());
        let mut fsorted = frontier.clone(); fsorted.sort();
        let mut expect = vec![vm.intern_atom("3"), vm.intern_atom("4")]; expect.sort();
        assert_eq!(fsorted, expect, "entry frontier should be exactly {{3,4}}");
        // splice through the thin frontier == full enumeration for periphery seeds.
        vm.build_boundary_suffix(&frontier, root, budget, "category_parent");
        let pseeds: Vec<u32> = ["10", "11", "12"].iter().map(|s| vm.intern_atom(s)).collect();
        let acc = vm.resolve_edge_accessor("category_parent");
        for &s in &pseeds {
            let mut fh = vec![]; let mut v = vec![s];
            vm.enum_ancestor_hist(s, root, &mut v, budget, &acc, 0, &mut fh);
            let wref = crate::boundary_cache::f_weighted_power(&fh, n);
            let mut bh = vec![]; let mut v2 = vec![s];
            vm.collect_native_category_ancestor_boundary_hist(s, root, &mut v2, budget, &acc, 0, &mut bh);
            let wsp = crate::boundary_cache::f_weighted_power(&bh, n);
            assert!((wref - wsp).abs() < 1e-12, "frontier seed {}: {} != {}", s, wref, wsp);
            assert!(wref > 0.0, "seed {} should reach root", s);
        }
    }

    // Lazy (demand-driven) boundary cache: identical results to eager, but only the
    // band-entry nodes a query actually touches are ever computed/cached.
    #[test]
    fn lazy_boundary_caches_on_demand_and_matches_eager() {
        let mut vm = WamState::new(vec![], HashMap::new());
        vm.register_ffi_fact_pairs("category_parent", &[
            ("1", "0"), ("2", "0"), ("3", "1"), ("4", "2"),
            ("10", "3"), ("10", "4"), ("11", "3"), ("12", "10"),
        ]);
        let root = vm.intern_atom("0");
        let budget = 8usize;
        let n = 2.0f64;
        let mut md: HashMap<i32, i32> = HashMap::new();
        for (name, d) in [("0",0),("1",1),("2",1),("3",2),("4",2),("10",3),("11",3),("12",4)] {
            md.insert(vm.intern_atom(name) as i32, d);
        }
        vm.set_min_dist(&md);
        let pseeds: Vec<u32> = ["10", "11", "12"].iter().map(|s| vm.intern_atom(s)).collect();
        let n3 = vm.intern_atom("3");
        // production reference per seed
        let prod: Vec<f64> = {
            let acc = vm.resolve_edge_accessor("category_parent");
            pseeds.iter().map(|&s| {
                let mut fh = vec![]; let mut v = vec![s];
                vm.enum_ancestor_hist(s, root, &mut v, budget, &acc, 0, &mut fh);
                crate::boundary_cache::f_weighted_power(&fh, n)
            }).collect()
        };
        // lazy over JUST seed 11 -> caches only its entry (node 3), not node 4.
        assert!(vm.boundary_suffix.is_empty());
        let s11 = vm.intern_atom("11");
        let r11 = vm.lazy_boundary_weightsum(&[s11], root, budget, "category_parent", 2, n);
        assert!((r11[0] - prod[1]).abs() < 1e-12, "lazy result must match production");
        assert_eq!(vm.boundary_suffix.len(), 1, "lazy cached only the touched entry");
        assert!(vm.boundary_suffix.contains_key(&n3), "the touched entry is node 3");
        // lazy over all seeds -> cache grows to both entries {3,4}, results exact.
        let rall = vm.lazy_boundary_weightsum(&pseeds, root, budget, "category_parent", 2, n);
        for (i, _) in pseeds.iter().enumerate() {
            assert!((rall[i] - prod[i]).abs() < 1e-12, "seed#{} lazy != production", i);
        }
        assert_eq!(vm.boundary_suffix.len(), 2, "now both entries {{3,4}} are cached");
    }

    // P4: opt-in storage-gated compression of the boundary table — work-triggered
    // by support count, certified by epsilon_K, and a no-op on short histograms.
    #[test]
    fn compress_boundary_suffix_is_opt_in_and_certified() {
        let mut vm = WamState::new(vec![], HashMap::new());
        // one long low-tail histogram (compressible), one short one (untouched).
        let mut long = vec![0u64; 60];
        long[0] = 1_000_000;
        for i in 50..60 { long[i] = 1; }
        let short = vec![900u64, 1, 1];
        let mut table: HashMap<u32, Vec<u64>> = HashMap::new();
        table.insert(1, long.clone());
        table.insert(2, short.clone());
        vm.set_boundary_suffix(&table);
        let (compressed, removed) = vm.compress_boundary_suffix(50, 0.001);
        assert_eq!(compressed, 1, "only the long low-tail histogram compresses");
        assert!(removed > 0);
        let got_long = vm.boundary_suffix.get(&1).unwrap();
        assert!(got_long.len() < long.len(), "long histogram shortened");
        assert!(crate::boundary_cache::cdf_max_error(&long, got_long) <= 0.001 + 1e-9,
            "compression stays within epsilon_K");
        assert_eq!(vm.boundary_suffix.get(&2).unwrap(), &short, "short histogram untouched");
    }

    // P4: the pre-weighted weighted_power basis (g_B dot-product splice) yields the
    // SAME WeightSum as the histogram-based weighted_power == full enumeration.
