    #[cfg(all(unix, target_pointer_width = "64"))]
    fn process_soft_limit(resource: i64) -> Option<i64> {
        #[repr(align(16))]
        struct LimitBuffer([u8; 16]);
        extern "C" {
            fn getrlimit(
                resource: std::os::raw::c_int,
                limits: *mut std::ffi::c_void,
            ) -> std::os::raw::c_int;
        }

        let mut limits = LimitBuffer([0u8; 16]);
        if unsafe { getrlimit(resource as std::os::raw::c_int,
                              limits.0.as_mut_ptr().cast()) } != 0 {
            return None;
        }
        let current = unsafe {
            std::ptr::read_unaligned(limits.0.as_ptr().cast::<u64>())
        };
        Some(current as i64)
    }

    #[cfg(not(all(unix, target_pointer_width = "64")))]
    fn process_soft_limit(_resource: i64) -> Option<i64> {
        None
    }

    #[cfg(all(unix, target_pointer_width = "64"))]
    fn set_process_soft_limit(resource: i64, limit: i64) -> bool {
        #[repr(align(16))]
        struct LimitBuffer([u8; 16]);
        extern "C" {
            fn getrlimit(
                resource: std::os::raw::c_int,
                limits: *mut std::ffi::c_void,
            ) -> std::os::raw::c_int;
            fn setrlimit(
                resource: std::os::raw::c_int,
                limits: *const std::ffi::c_void,
            ) -> std::os::raw::c_int;
        }

        let mut limits = LimitBuffer([0u8; 16]);
        let resource = resource as std::os::raw::c_int;
        if unsafe { getrlimit(resource, limits.0.as_mut_ptr().cast()) } != 0 {
            return false;
        }
        unsafe {
            std::ptr::write_unaligned(
                limits.0.as_mut_ptr().cast::<u64>(), limit as u64)
        };
        unsafe { setrlimit(resource, limits.0.as_ptr().cast()) == 0 }
    }

    #[cfg(not(all(unix, target_pointer_width = "64")))]
    fn set_process_soft_limit(_resource: i64, _limit: i64) -> bool {
        false
    }

